import pandas as pd
from math import radians, sin, cos, sqrt, atan2
stations = pd.read_csv('/app/dataset/stations.csv')
readings = pd.read_csv('/app/dataset/readings.csv', parse_dates=['timestamp'])
station_poll = readings.groupby('station_id')['pollutant'].agg(lambda s: s.mode().iloc[0])
stations = stations.merge(station_poll.rename('pollutant'), on='station_id')
panel = readings.pivot(index='timestamp', columns='station_id', values='current_reading').sort_index()
panel_i = panel.interpolate(limit=2, limit_direction='both', limit_area='inside')
coords = stations.set_index('station_id')[['latitude','longitude']]
R=6371.0
D={}
for sid,(lat1,lon1) in coords.iterrows():
    for oid,(lat2,lon2) in coords.iterrows():
        dlat=radians(lat2-lat1); dlon=radians(lon2-lon1)
        a=sin(dlat/2)**2 + cos(radians(lat1))*cos(radians(lat2))*sin(dlon/2)**2
        D[(sid,oid)] = 2*R*atan2(sqrt(a),sqrt(1-a))

def peers(sid):
    row=stations.set_index('station_id').loc[sid]
    cand=stations[(stations.station_id!=sid)&(stations.pollutant==row.pollutant)].copy()
    within=cand[cand.district==row.district].copy(); within['dist']=within['station_id'].map(lambda x:D[(sid,x)])
    if len(within)>=4:
        return within.sort_values('dist').head(4)['station_id'].tolist()
    cand['dist']=cand['station_id'].map(lambda x:D[(sid,x)])
    return cand.sort_values('dist').head(4)['station_id'].tolist()
for sid in ['ST014','ST051','ST026','ST040','ST025','ST035','ST066','ST046','ST065']:
    p=peers(sid)
    df=pd.DataFrame({'target':panel[sid],'target_i':panel_i[sid],'peer_mean':panel_i[p].mean(axis=1)})
    for pid in p:
        df[pid]=panel_i[pid]
    # zscores for target_i and peer_mean
    for col in ['target_i','peer_mean']:
        df[col+'_z']=(df[col]-df[col].mean())/df[col].std()
    print('\n===',sid,'peers',p,'===')
    print(df[['target','target_i','peer_mean','target_i_z','peer_mean_z']].round(2).to_string())
